func (tuplet_portion *Tuplet_portion) GongGetFieldValue(fieldName string, stage *Stage) (res GongFieldValue) {
	switch fieldName {
	// string value of fields
	case "Name":
		res.valueString = tuplet_portion.Name
	case "Tuplet_number":
		res.GongFieldValueType = GongFieldValueTypePointer
		if tuplet_portion.Tuplet_number != nil {
			res.valueString = tuplet_portion.Tuplet_number.Name
			res.ids = tuplet_portion.Tuplet_number.GongGetUUID(stage)
		}
	case "Tuplet_type":
		res.GongFieldValueType = GongFieldValueTypePointer
		if tuplet_portion.Tuplet_type != nil {
			res.valueString = tuplet_portion.Tuplet_type.Name
			res.ids = tuplet_portion.Tuplet_type.GongGetUUID(stage)
		}
	case "Tuplet_dot":
		res.GongFieldValueType = GongFieldValueTypeSliceOfPointers
		for idx, __instance__ := range tuplet_portion.Tuplet_dot {
			if idx > 0 {
				res.valueString += "\n"
				res.ids += ";"
			}
			res.valueString += __instance__.Name
			res.ids += __instance__.GongGetUUID(stage)
		}
	}
	return
}

